import React, { useEffect, useState } from "react";
import axios from "axios";
import PageHeader from "./PageHeader";
import SectionCard from "./SectionCard";
import DashboardCard from "./DashboardCard";
import AlertBox from "./AlertBox";
import { FaTasks, FaPlusCircle, FaBookOpen, FaCheckCircle } from "react-icons/fa";
import "./dashboard.css";

function QuizTeacher() {
  const teacherId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [courseId, setCourseId] = useState("");
  const [title, setTitle] = useState("");
  const [quizId, setQuizId] = useState(null);
  const [alert, setAlert] = useState(null);

  const [question, setQuestion] = useState("");
  const [options, setOptions] = useState(["", "", "", ""]);
  const [correctIndex, setCorrectIndex] = useState(null);

  useEffect(() => {
    axios
      .get("http://127.0.0.1:8000/courses")
      .then((res) => {
        const allCourses = res.data.courses || [];
        const myCourses = allCourses.filter(
          (c) => String(c.teacher_id) === String(teacherId)
        );
        setCourses(myCourses);
      })
      .catch((err) => console.error(err));
  }, [teacherId]);

  const createQuiz = async () => {
    if (!courseId || !title) {
      setAlert({
        message: "Please select a course and enter quiz title",
        type: "error"
      });
      return;
    }

    try {
      const res = await axios.post("http://127.0.0.1:8000/create-quiz", {
        course_id: parseInt(courseId),
        teacher_id: parseInt(teacherId),
        title: title
      });

      setQuizId(res.data.quiz_id);
      setAlert({
        message: res.data.message || "Quiz created successfully",
        type: "success"
      });
    } catch (err) {
      console.error(err);
      setAlert({
        message: "Quiz creation failed",
        type: "error"
      });
    }
  };

  const addQuestion = async () => {
    if (!quizId) {
      setAlert({
        message: "Create quiz first",
        type: "error"
      });
      return;
    }

    if (correctIndex === null) {
      setAlert({
        message: "Select correct option",
        type: "error"
      });
      return;
    }

    try {
      await axios.post("http://127.0.0.1:8000/add-question", {
        quiz_id: quizId,
        question: question,
        option1: options[0],
        option2: options[1],
        option3: options[2],
        option4: options[3],
        correct_answer: options[correctIndex]
      });

      setAlert({
        message: "Question added successfully",
        type: "success"
      });

      setQuestion("");
      setOptions(["", "", "", ""]);
      setCorrectIndex(null);
    } catch (err) {
      console.error(err);
      setAlert({
        message: "Failed to add question",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <PageHeader
        title="Quiz Teacher Panel"
        subtitle="Create subject-wise quizzes and add questions with correct answer selection."
      />

      <div className="grid-4" style={{ marginBottom: "18px" }}>
        <DashboardCard
          icon={<FaBookOpen />}
          label="My Courses"
          value={courses.length}
        />
        <DashboardCard
          icon={<FaTasks />}
          label="Quiz Status"
          value={quizId ? "Created" : "Pending"}
        />
        <DashboardCard
          icon={<FaPlusCircle />}
          label="Question Mode"
          value={quizId ? "Enabled" : "Locked"}
        />
        <DashboardCard
          icon={<FaCheckCircle />}
          label="Current Quiz ID"
          value={quizId || "N/A"}
        />
      </div>

      <div className="grid-2">
        <SectionCard title="Create Quiz">
          <select
            className="select"
            value={courseId}
            onChange={(e) => setCourseId(e.target.value)}
          >
            <option value="">Select Subject / Course</option>
            {courses.map((c) => (
              <option key={c.id} value={c.id}>
                {c.title} {c.subject_code ? `(${c.subject_code})` : ""}
              </option>
            ))}
          </select>

          <input
            className="input"
            type="text"
            placeholder="Quiz Title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />

          <button className="btn btn-primary" onClick={createQuiz}>
            Create Quiz
          </button>
        </SectionCard>

        <SectionCard title="Add Question">
          <input
            className="input"
            type="text"
            placeholder="Enter Question"
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
          />

          {options.map((opt, i) => (
            <div
              key={i}
              style={{
                display: "flex",
                gap: "10px",
                alignItems: "center",
                marginBottom: "10px"
              }}
            >
              <input
                className="input"
                style={{ marginBottom: 0 }}
                type="text"
                placeholder={`Option ${i + 1}`}
                value={opt}
                onChange={(e) => {
                  const arr = [...options];
                  arr[i] = e.target.value;
                  setOptions(arr);
                }}
              />

              <label style={{ minWidth: "110px", fontWeight: "600" }}>
                <input
                  type="radio"
                  name="correct"
                  checked={correctIndex === i}
                  onChange={() => setCorrectIndex(i)}
                />
                {" "}Correct
              </label>
            </div>
          ))}

          <button className="btn btn-primary" onClick={addQuestion}>
            Add Question
          </button>
        </SectionCard>
      </div>
    </div>
  );
}

export default QuizTeacher;
